Core.utils.deferBootstrap({elId:'bs-8',componentName:'@widget/HTML/bs-Component',props:JSON.parse("{\"data-aid\":\"AUTOIFRAME_RENDERED\",\"htmlSrc\":\"\u003C!-- ================= SciTOX Landing Section (Drop-in HTML) ================= -->\\n<section id=\\\"scitox-landing\\\" class=\\\"scitox\\\">\\n  <style>\\n    :root{\\n      /* ==== Tweak these to match your brand ==== */\\n      --brand:#0e9271;         /* primary */\\n      --brand-dark:#0a7e61;    /* primary hover */\\n      --accent:#0f172a;        /* headings/text */\\n      --muted:#475569;         /* body text */\\n      --bg:#f8fafc;            /* section bg */\\n      --card:#ffffff;          /* card bg */\\n      --ring:#d1fae5;          /* subtle outline */\\n      --shadow:0 10px 25px rgba(2,8,23,.08);\\n      --radius:18px;\\n    }\\n    .scitox{font-family: system-ui,-apple-system,Segoe UI,Roboto,Inter,Arial,sans-serif;background:var(--bg);color:var(--muted);padding:48px 16px}\\n    .scx-container{max-width:1100px;margin:0 auto}\\n    .scx-hero{display:grid;gap:18px;margin-bottom:28px}\\n    .scx-hero h1{color:var(--accent);font-size:clamp(28px,4vw,40px);line-height:1.1;margin:0}\\n    .scx-sub{font-size:clamp(16px,1.6vw,18px);color:var(--muted)}\\n    .scx-badges{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:6px 0 0}\\n    .scx-badges .badge{display:inline-flex;align-items:center;gap:8px;background:var(--card);border:1px solid #e5e7eb;border-radius:999px;padding:8px 12px;box-shadow:var(--shadow)}\\n    .scx-badges svg{width:18px;height:18px}\\n    .scx-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px}\\n    .btn{appearance:none;border:0;border-radius:12px;padding:14px 18px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:10px;box-shadow:var(--shadow)}\\n    .btn-primary{background:var(--brand);color:#fff}\\n    .btn-primary:hover{background:var(--brand-dark)}\\n    .btn-ghost{background:var(--card);color:var(--accent);border:1px solid #e5e7eb}\\n    .scx-grid{display:grid;grid-template-columns:1fr;gap:18px;margin-top:26px}\\n    @media (min-width:900px){.scx-grid{grid-template-columns:1.1fr .9fr}}\\n    .card{background:var(--card);border:1px solid #e5e7eb;border-radius:var(--radius);box-shadow:var(--shadow);padding:22px}\\n    .card h3{color:var(--accent);margin:0 0 10px;font-size:20px}\\n    .list{display:grid;gap:10px;margin:0;padding:0;list-style:none}\\n    .list li{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:start}\\n    .chip{font-size:12px;font-weight:700;color:#065f46;background:var(--ring);padding:4px 8px;border-radius:999px}\\n    .split{display:grid;gap:10px}\\n    .divider{height:1px;background:#e5e7eb;margin:14px 0}\\n    .note{font-size:13px;color:#334155}\\n    .disclaimers{font-size:12px;color:#64748b}\\n    .pill{display:inline-block;background:#e2e8f0;border-radius:999px;padding:6px 10px;font-weight:700;font-size:12px;color:#0f172a}\\n    .kicker{display:inline-flex;gap:8px;align-items:center}\\n    .kicker .dot{width:8px;height:8px;background:var(--brand);border-radius:50%}\\n    /* Trust badge row stand-alone (footer) */\\n    .trust-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\\n    .trust-row .mini{font-size:12px;color:#0f172a;background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:8px 10px;display:inline-flex;gap:8px;align-items:center}\\n    .trust-row svg{width:16px;height:16px}\\n  <\/style>\\n\\n  <div class=\\\"scx-container\\\">\\n\\n    \u003C!-- Hero -->\\n    <div class=\\\"scx-hero\\\">\\n      <div class=\\\"kicker\\\"><span class=\\\"dot\\\"></span><span class=\\\"pill\\\">Permanent Hair Detox \u2014 Not a Mask</span></div>\\n      <h1>Pass Your Hair Follicle Drug Test with SciTOX</h1>\\n      <p class=\\\"scx-sub\\\">Scientifically engineered, 7+ step system that penetrates the cortex to remove metabolites at the molecular level. Most customers complete in about <strong>3 hours*</strong>.</p>\\n\\n      \u003C!-- Trust badges -->\\n      <div class=\\\"scx-badges\\\" aria-label=\\\"Trust & Assurance\\\">\\n        \u003C!-- BBB -->\\n        <a class=\\\"badge\\\" href=\\\"#\\\" target=\\\"_blank\\\" rel=\\\"nofollow noopener\\\" aria-label=\\\"BBB Accredited (replace # with your BBB profile URL)\\\">\\n          <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" aria-hidden=\\\"true\\\"><path d=\\\"M6 3h12v18H6z\\\" stroke=\\\"#0ea5e9\\\" stroke-width=\\\"1.5\\\"/><path d=\\\"M12 5.5l2 2-2 2-2-2 2-2z\\\" fill=\\\"#0ea5e9\\\"/></svg>\\n          <span>BBB Accredited</span>\\n        </a>\\n        \u003C!-- Trustpilot -->\\n        <a class=\\\"badge\\\" href=\\\"#\\\" target=\\\"_blank\\\" rel=\\\"nofollow noopener\\\" aria-label=\\\"Trustpilot Reviews (replace # with your Trustpilot URL)\\\">\\n          <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" aria-hidden=\\\"true\\\"><path d=\\\"M12 2l2.3 6.9h7.2l-5.8 4.2 2.2 6.9L12 15.8 6.1 20l2.2-6.9L2.5 8.9h7.2L12 2z\\\" fill=\\\"#10b981\\\"/></svg>\\n          <span>Trustpilot Reviews</span>\\n        </a>\\n        \u003C!-- Yotpo -->\\n        <a class=\\\"badge\\\" href=\\\"#\\\" target=\\\"_blank\\\" rel=\\\"nofollow noopener\\\" aria-label=\\\"Yotpo Verified (replace # with your Yotpo URL)\\\">\\n          <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" aria-hidden=\\\"true\\\"><circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"9\\\" stroke=\\\"#111827\\\" stroke-width=\\\"1.5\\\"/><path d=\\\"M8.5 9.5h7M8.5 12h7M8.5 14.5h4\\\" stroke=\\\"#111827\\\" stroke-width=\\\"1.5\\\" stroke-linecap=\\\"round\\\"/></svg>\\n          <span>Yotpo Verified</span>\\n        </a>\\n        \u003C!-- SSL -->\\n        <span class=\\\"badge\\\" aria-label=\\\"Secure checkout\\\">\\n          <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" aria-hidden=\\\"true\\\"><rect x=\\\"4\\\" y=\\\"9\\\" width=\\\"16\\\" height=\\\"10\\\" rx=\\\"2\\\" stroke=\\\"#22c55e\\\" stroke-width=\\\"1.5\\\"/><path d=\\\"M8 9V7a4 4 0 018 0v2\\\" stroke=\\\"#22c55e\\\" stroke-width=\\\"1.5\\\"/></svg>\\n          <span>SSL Secure Checkout</span>\\n        </span>\\n        \u003C!-- Money-back -->\\n        <span class=\\\"badge\\\" aria-label=\\\"Satisfaction guarantee\\\">\\n          <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" aria-hidden=\\\"true\\\"><circle cx=\\\"12\\\" cy=\\\"12\\\" r=\\\"9\\\" stroke=\\\"#f59e0b\\\" stroke-width=\\\"1.5\\\"/><path d=\\\"M7.5 13c1.2 1 2.7 1.5 4.5 1.5s3.3-.5 4.5-1.5\\\" stroke=\\\"#f59e0b\\\" stroke-width=\\\"1.5\\\" stroke-linecap=\\\"round\\\"/><circle cx=\\\"9\\\" cy=\\\"10\\\" r=\\\"1\\\" fill=\\\"#f59e0b\\\"/><circle cx=\\\"15\\\" cy=\\\"10\\\" r=\\\"1\\\" fill=\\\"#f59e0b\\\"/></svg>\\n          <span>Money-Back Guarantee</span>\\n        </span>\\n      </div>\\n\\n      \u003C!-- CTAs -->\\n      <div class=\\\"scx-cta\\\">\\n        <a class=\\\"btn btn-primary\\\" href=\\\"https://scitoxdetox.com/online-store\\\">Shop the SciTOX System</a>\\n        <a class=\\\"btn btn-ghost\\\" href=\\\"https://scitoxdetox.com/results-%26-testimonials\\\">See Real Results & Proof</a>\\n        <a class=\\\"btn btn-ghost\\\" href=\\\"https://scitoxdetox.com/process\\\">How It Works</a>\\n      </div>\\n    </div>\\n\\n    \u003C!-- Content Grid -->\\n    <div class=\\\"scx-grid\\\">\\n\\n      \u003C!-- Left: How it Works -->\\n      <div class=\\\"card\\\">\\n        <h3>How It Works</h3>\\n        <ul class=\\\"list\\\">\\n          <li><span class=\\\"chip\\\">Steps 1\u20132</span><div>Deep cleanse scalp & surface; begin cuticle penetration.</div></li>\\n          <li><span class=\\\"chip\\\">Step 3</span><div>Opens cuticle, breaks melanin\u2013metabolite bonds, reduces/oxidizes/degrades metabolites. <strong>Use UV light</strong> to exponentially accelerate reactions.</div></li>\\n          <li><span class=\\\"chip\\\">Step 4 (Optional)</span><div>Optimized bleach & developer removes <strong>2\u20133\u00D7</strong> more metabolites vs. regular bleach. <strong>Highly recommended for THC</strong>.</div></li>\\n          <li><span class=\\\"chip\\\">Step 5</span><div>Redye to your shade (purchased separately) & further flush metabolites.</div></li>\\n          <li><span class=\\\"chip\\\">Step 6</span><div>Re-opens cuticle; rearranges keratin to detach metabolite bonds and leach them out.</div></li>\\n          <li><span class=\\\"chip\\\">Step 7</span><div>Final cleanse to remove residuals; reseals cuticle to lock in the clean state.</div></li>\\n          <li><span class=\\\"chip\\\">Step 8 (Optional)</span><div>UV Light synergy rapidly oxidizes & destroys metabolites at the molecular level.</div></li>\\n        </ul>\\n\\n        <div class=\\\"divider\\\"></div>\\n        <p class=\\\"note\\\"><strong>Rounds:</strong> For best results complete at least <strong>4 full rounds of Steps 1\u20133</strong> before moving on.</p>\\n        <p class=\\\"note\\\"><strong>Timing:</strong> Can be done in <strong>one sitting</strong> for emergencies; recommended to spread over <strong>3+ days</strong> (ideally <strong>~1 week</strong>) for scalp & hair health.</p>\\n      </div>\\n\\n      \u003C!-- Right: Why SciTOX + What's Included -->\\n      <div class=\\\"split\\\">\\n        <div class=\\\"card\\\">\\n          <h3>Why SciTOX?</h3>\\n          <ul class=\\\"list\\\">\\n            <li><span class=\\\"chip\\\">Permanent</span><div>Real chemical detox \u2014 <strong>not a masking shampoo</strong>.</div></li>\\n            <li><span class=\\\"chip\\\">Fast</span><div>Finish in as little as <strong>~3 hours*</strong>.</div></li>\\n            <li><span class=\\\"chip\\\">Proven</span><div><strong>Thousands</strong> of satisfied customers; developed over <strong>10+ years</strong>.</div></li>\\n            <li><span class=\\\"chip\\\">THC Tough</span><div><strong>Bleach + UV</strong> combo is our strongest path for short timelines.</div></li>\\n            <li><span class=\\\"chip\\\">Lab-Smart</span><div>Targets cortex & keratin bonds; labs can\u2019t detect a \u201Cmask\u201D because it isn\u2019t one.</div></li>\\n          </ul>\\n          <div class=\\\"trust-row\\\" aria-label=\\\"Assurances\\\">\\n            <span class=\\\"mini\\\">\\n              <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\"><path d=\\\"M4 12l5 5L20 6\\\" stroke=\\\"#22c55e\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\"/></svg>\\n              Zero masking agents\\n            </span>\\n            <span class=\\\"mini\\\">\\n              <svg viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\"><path d=\\\"M12 3l6 3v5c0 4.418-2.686 8.418-6 10-3.314-1.582-6-5.582-6-10V6l6-3z\\\" stroke=\\\"#0ea5e9\\\" stroke-width=\\\"1.5\\\"/></svg>\\n              Science-first formula\\n            </span>\\n          </div>\\n        </div>\\n\\n        <div class=\\\"card\\\">\\n          <h3>What\u2019s Included</h3>\\n          <ul class=\\\"list\\\">\\n            <li><span class=\\\"chip\\\">1\u20133</span><div>Cleansing & cuticle-opening treatments.</div></li>\\n            <li><span class=\\\"chip\\\">4 (Opt.)</span><div>Optimized bleach & developer (best for THC/short timelines).</div></li>\\n            <li><span class=\\\"chip\\\">5</span><div>Redye (purchase to match your color; a shade darker is fine).</div></li>\\n            <li><span class=\\\"chip\\\">6\u20137</span><div>Keratin detox + final cleanse & seal.</div></li>\\n            <li><span class=\\\"chip\\\">8 (Opt.)</span><div>UV Light device for maximum speed & power.</div></li>\\n          </ul>\\n          <div class=\\\"scx-cta\\\">\\n            <a class=\\\"btn btn-primary\\\" href=\\\"https://scitoxdetox.com/online-store\\\">Get the Right Kit</a>\\n            <a class=\\\"btn btn-ghost\\\" href=\\\"https://scitoxdetox.com/results-%26-testimonials\\\">See Proof & Testimonials</a>\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n\\n    \u003C!-- Consult -->\\n    <div class=\\\"card\\\" style=\\\"margin-top:22px\\\">\\n      <h3>Free Fast Consultation</h3>\\n      <p>Text or call us with: what you used, how much/how often, how long, when your last use was, plus your hair length & color \u2014 we\u2019ll tell you the exact kit and timeline.</p>\\n      <div class=\\\"scx-cta\\\">\\n        <a class=\\\"btn btn-primary\\\" href=\\\"https://scitoxdetox.com/online-store\\\">Start Now</a>\\n        <a class=\\\"btn btn-ghost\\\" href=\\\"https://scitoxdetox.com/process\\\">Read the Full Process</a>\\n      </div>\\n      <p class=\\\"disclaimers\\\" style=\\\"margin-top:12px\\\">\\n        *Most customers complete the process in ~3 hours for heavy use of certain toxins and light use of others. \\n        Heavy use of other toxins may require additional time. Results depend on substance type, usage history, hair characteristics, and adherence to instructions.\\n        New growth may reintroduce metabolites after ~10\u201314 days; by ~45 days, ~\u00BD inch of new growth could be within collection length.\\n      </p>\\n    </div>\\n\\n    \u003C!-- Optional: Proof gallery deep-links (uncomment if you add a dedicated gallery section) -->\\n    \u003C!-- <div class=\\\"card\\\" style=\\\"margin-top:22px\\\">\\n      <h3>Proof Gallery</h3>\\n      <p>Explore visual results and step-by-step outcomes.</p>\\n      <div class=\\\"scx-cta\\\">\\n        <a class=\\\"btn btn-ghost\\\" href=\\\"https://scitoxdetox.com/results-%26-testimonials\\\">See Results Gallery</a>\\n      </div>\\n    </div> -->\\n\\n  </div>\\n</section>\\n\u003C!-- ================= /SciTOX Landing Section ================= -->\\n\",\"widgetId\":\"c2ed93d1-373a-446a-9e3f-521f7c97a966\",\"section\":\"alt\",\"category\":\"accent\",\"locale\":\"en-US\",\"env\":\"production\",\"renderMode\":\"PUBLISH\"}"),context:JSON.parse("{\"order\":1,\"widgetId\":\"c2ed93d1-373a-446a-9e3f-521f7c97a966\",\"widgetType\":\"HTML\",\"widgetPreset\":\"html1\",\"group\":\"Section\",\"groupType\":\"Default\",\"section\":\"alt\",\"category\":\"accent\",\"fontSize\":\"medium\",\"fontFamily\":\"alternate\",\"websiteThemeOverrides\":{},\"widgetThemeOverrides\":{}}"),contextKey:'context-bs-7',radpack:"@widget/HTML/bs-Component"},false);
